import{_ as a,o,c as r,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Organize automações","description":"","frontmatter":{"title":"Organize automações","docId":"user.automations.index","translationKey":"user.automations.index","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"33d5d9aa4db49a70a3b416ea817479822f06d7cb028699ab9bd344c14cd79892","translationRevision":"50616be9e5b99a01a92dc79f2e247512fa7c72a684de06cd06694d578834467c","order":10},"headers":[],"relativePath":"pt/user/automations/index.md","filePath":"pt/user/automations/index.md","lastUpdated":1794611623000}'),t={name:"pt/user/automations/index.md"};function i(n,e,d,l,u,c){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="organize-automations" tabindex="-1">Organize automações <a class="header-anchor" href="#organize-automations" aria-label="Permalink to &quot;Organize automações {#organize-automations}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Crie uma biblioteca pequena e compreensível que responda a eventos de LIVE. Você precisa de um host de desktop funcional. Uma <a href="./../live/connections.html">conexão real com uma LIVE</a> é necessária para validar os eventos recebidos do serviço; ações de plugins também exigem que o plugin e seu serviço estejam prontos.</p><h2 id="understand-the-library" tabindex="-1">Entenda a biblioteca <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to &quot;Entenda a biblioteca {#understand-the-library}&quot;">​</a></h2><p>Uma <strong>Action</strong> é uma operação configurada reutilizável, como escrever uma linha no registro ou tocar um som. Um <strong>Event</strong> define um acionador, filtros, intervalo de espera e ações vinculadas. Um perfil agrupa definições de um fluxo de trabalho; apenas um pacote de perfil fica ativo por vez. As <a href="./variables.html">Variables</a> de execução fornecem valores que várias ações podem reutilizar.</p><ol><li>Abra <strong>Automations</strong> e confirme o perfil ativo antes de editar. Pesquise Events e Actions separadamente para saber qual tipo de registro está selecionando.</li><li>Comece pela <a href="./first-rule.html">primeira regra de registro</a>. Crie sua ação e depois um evento que a referencie.</li><li>Escolha um acionador aceito pelo host atual. Use o seletor de campos para adicionar filtros desse acionador. Várias condições restringem as correspondências; elas não alteram os dados recebidos.</li><li>Defina um intervalo de espera e seu escopo. Um intervalo global limita a regra entre todos os espectadores; um intervalo por usuário acompanha cada espectador separadamente.</li><li>Vincule as ações desejadas na ordem. O modo normal executa a lista escolhida; o modo aleatório seleciona uma ação dela. Uma ação de atraso adia as ações seguintes, sem reduzir a velocidade de ingestão da LIVE.</li><li>Salve, revise as alterações de definição exibidas e ative explicitamente os registros que pretende executar. Confira no histórico de execução o nome da ação, o resultado e o erro.</li></ol><p>Os testes podem executar os efeitos configurados. Leia a lista de ações selecionadas antes de pressionar <strong>Test</strong> ou disparar um evento, especialmente para áudio, HTTP, pontos e operações de plugins. Use registros enquanto aprende.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Edição local, execução, modelos, perfis e histórico estão disponíveis. Acionadores de plugins aparecem apenas enquanto o plugin correspondente está instalado e ativo. A ativação depende da superfície e dos valores enabled revisados; confira eventos e ações antes de confirmar. O painel <strong>Changes</strong> de Events/Actions é uma <a href="./../cloud/changes.html">comparação com referência local</a>, não um envio automático ao Cloud.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Quando não houver execução, verifique perfil ativo, estados de ativação, acionador, filtros, intervalo de espera e ações ausentes, nessa ordem. Para um conflito de revisão, leia a definição salva atual e revise novamente. Não sobrescreva a atualização de outra pessoa às cegas. Exporte um <a href="./templates.html">perfil</a> que funcione antes de fazer alterações amplas.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Antes de trocar perfil/importar, leia <a href="./templates.html#operational-details">ativação por superfície</a>. A troca pode ativar membros desativados individualmente. Cooldown fica em memória, limitado a 24 horas; sem uniqueId os espectadores compartilham escopo anônimo. A tabela esvazia ao atingir 8.192 chaves: sobrecarga ou reinício podem permitir execuções adicionais. Não é cota durável nem garantia contra replay.</p>',13)])])}const h=a(t,[["render",i]]);export{m as __pageData,h as default};
